package com.wtm.ui;
import javax.swing.*;import javax.swing.border.*;import java.awt.*;import java.awt.event.*;import java.io.File;import java.nio.file.*;import java.util.*;
public final class NorthStarFileDialog{
 public static Path open(Component owner,String title,String...ext){return show(owner,title,false,null,ext);}public static Path save(Component owner,String title,String filename){return show(owner,title,true,filename);}
 private static Path show(Component owner,String title,boolean save,String filename,String...ext){Window w=SwingUtilities.getWindowAncestor(owner);JDialog d=new JDialog(w,title,Dialog.ModalityType.APPLICATION_MODAL);d.setDefaultCloseOperation(WindowConstants.DISPOSE_ON_CLOSE);d.setSize(780,560);d.setLocationRelativeTo(owner);JPanel root=new JPanel(new BorderLayout(10,10));root.setBackground(Theme.bg());root.setBorder(new EmptyBorder(16,16,16,16));d.setContentPane(root);final Path[] dir={Path.of(System.getProperty("user.home"))},result={null};JLabel path=new JLabel();path.setForeground(Theme.muted());DefaultListModel<File> model=new DefaultListModel<>();JList<File> list=new JList<>(model);list.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);list.setCellRenderer((l,v,i,s,f)->{JLabel x=new JLabel((v.isDirectory()?"▣  ":"    ")+v.getName());x.setOpaque(true);x.setBorder(new EmptyBorder(7,9,7,9));x.setBackground(s?Theme.accent():Theme.panel());x.setForeground(s?Color.WHITE:Theme.text());return x;});Runnable load=()->{model.clear();path.setText(dir[0].toString());File[]fs=dir[0].toFile().listFiles();if(fs!=null){Arrays.sort(fs,Comparator.comparing(File::isFile).thenComparing(x->x.getName().toLowerCase()));for(File f:fs){if(f.isDirectory()){model.addElement(f);continue;}if(save||ext.length==0||matches(f,ext))model.addElement(f);}}};JPanel top=new JPanel(new BorderLayout(8,0));top.setOpaque(false);JButton up=new JButton("↑ Up"),home=new JButton("Home");JPanel nav=new JPanel(new FlowLayout(FlowLayout.LEFT,6,0));nav.setOpaque(false);nav.add(home);nav.add(up);top.add(nav,BorderLayout.WEST);top.add(path);root.add(top,BorderLayout.NORTH);JScrollPane sp=new JScrollPane(list);sp.setBorder(new LineBorder(Theme.border()));root.add(sp);JTextField name=new JTextField(filename==null?"":filename);JPanel bottom=new JPanel(new BorderLayout(8,8));bottom.setOpaque(false);if(save){JPanel np=new JPanel(new BorderLayout(8,0));np.setOpaque(false);JLabel nl=new JLabel("File name");nl.setForeground(Theme.text());np.add(nl,BorderLayout.WEST);np.add(name);bottom.add(np,BorderLayout.NORTH);}JPanel acts=new JPanel(new FlowLayout(FlowLayout.RIGHT,8,0));acts.setOpaque(false);JButton cancel=new JButton("Cancel"),ok=new JButton(save?"Save":"Open");acts.add(cancel);acts.add(ok);bottom.add(acts);root.add(bottom,BorderLayout.SOUTH);Runnable choose=()->{File f=list.getSelectedValue();if(!save&&f!=null&&f.isDirectory()){dir[0]=f.toPath();load.run();return;}Path p;if(save){String n=name.getText().trim();if(n.isBlank())return;p=dir[0].resolve(n);}else{if(f==null||f.isDirectory())return;p=f.toPath();}result[0]=p;d.dispose();};list.addMouseListener(new MouseAdapter(){public void mouseClicked(MouseEvent e){if(e.getClickCount()==2)choose.run();}});ok.addActionListener(e->choose.run());cancel.addActionListener(e->d.dispose());home.addActionListener(e->{dir[0]=Path.of(System.getProperty("user.home"));load.run();});up.addActionListener(e->{Path p=dir[0].getParent();if(p!=null){dir[0]=p;load.run();}});load.run();NorthStarThemeCompliance.apply(root);d.getRootPane().setDefaultButton(ok);d.setVisible(true);return result[0];}
 private static boolean matches(File f,String[] ext){String n=f.getName().toLowerCase();for(String e:ext)if(n.endsWith(e.toLowerCase().startsWith(".")?e.toLowerCase():"."+e.toLowerCase()))return true;return false;}private NorthStarFileDialog(){}
}
